import csv, io

TS = {
 "Core_mid": "855b75f9-c426-5619-badc-0df50869f3f6",
 "Perimeter_mid_ZN_1": "c778b459-3e21-5aaa-8431-ae20738126a6",
 "Perimeter_mid_ZN_2": "fb88e159-0c57-55dc-9ea2-3c40783af61d",
 "Perimeter_mid_ZN_3": "aafc228a-0978-55c3-8024-b29d1005133e",
 "Perimeter_mid_ZN_4": "4dd29768-4994-52f9-89cd-aa670d9e86f1",
}

TARGET = "2018-10-09 11:00"
# Also allow 11:00:00 / 10:00 if data starts on-hour
result = {}
with open(VALUES_CSV) as f:
    rdr = csv.reader(f)
    header = next(rdr)
    for row in rdr:
        tsid, ts, val = row[0], row[1], row[2]
        if tsid in TS.values() and ts.replace("T"," ")[:16] in (TARGET, TARGET+":00", TARGET+":00:00"):
            # match by start
            if ts.replace("T"," ").startswith("2018-10-09 11:00"):
                for zone, zid in TS.items():
                    if zid == tsid:
                        if zone not in result or float(val) > float(result[zone][1]):
                            result[zone] = (tsid, val, ts)
print(result)
best = max(result.items(), key=lambda kv: float(kv[1][1]))
print("HIGHEST:", best)
